import{_ as n,o as t,c as s,ag as r}from"./chunks/framework.D5hoimZQ.js";const m=JSON.parse('{"title":"🔬 科学日报 | 2026年10月25日 · 深度扩展","description":"","frontmatter":{"sidebar":true},"headers":[],"relativePath":"science-log/src/science-daily/2026-10-25.md","filePath":"science-log/src/science-daily/2026-10-25.md"}'),g={name:"science-log/src/science-daily/2026-10-25.md"};function e(a,o,i,c,p,d){return t(),s("div",null,[...o[0]||(o[0]=[r('<h1 id="🔬-科学日报-2026年10月25日-·-深度扩展" tabindex="-1">🔬 科学日报 | 2026年10月25日 · 深度扩展 <a class="header-anchor" href="#🔬-科学日报-2026年10月25日-·-深度扩展" aria-label="Permalink to &quot;🔬 科学日报 | 2026年10月25日 · 深度扩展&quot;">​</a></h1><blockquote><p>来源：科学快报 第44期 简讯（10 条：科学前沿 5 篇 + AI 前沿 5 篇） 分析日期：2026-10-25 版本：扩展版（10 条深度 + 交叉关联）</p></blockquote><hr><h2 id="🔬-一、科学前沿" tabindex="-1">🔬 一、科学前沿 <a class="header-anchor" href="#🔬-一、科学前沿" aria-label="Permalink to &quot;🔬 一、科学前沿&quot;">​</a></h2><h3 id="_1-柔性钙钛矿组件破-20-把-sam-与钙钛矿「拆开」分别沉积" tabindex="-1">1. 柔性钙钛矿组件破 20%：把 SAM 与钙钛矿「拆开」分别沉积 <a class="header-anchor" href="#_1-柔性钙钛矿组件破-20-把-sam-与钙钛矿「拆开」分别沉积" aria-label="Permalink to &quot;1. 柔性钙钛矿组件破 20%：把 SAM 与钙钛矿「拆开」分别沉积&quot;">​</a></h3><p><strong>原文</strong>：柔性钙钛矿太阳能组件（PSM）的效率与稳定性长期低于刚性器件，根因之一是柔性基底表面羟基容易脱附，破坏自组装单分子层（SAM）的锚定，进而扰乱钙钛矿结晶。作者提出一种「解耦的 SAM–钙钛矿共沉积」策略：通过降低 SAM 与钙钛矿之间的相互作用来加速 SAM 锚定，同时改善钙钛矿结晶。以碘化苯乙铵为钝化分子时，750 cm² 面积的柔性组件获得认证效率 20.2%；改用 1,3-丙二胺二氢碘盐作钝化剂时，14.55 cm² 器件效率达 22.0%，并在 85°C、65% 相对湿度的最大功率点跟踪下运行 1044 小时仅衰减 8%。器件还通过了柔性便携 PSM 国际商业化评估标准的所有序列测试。这说明制约柔性器件的不是材料本身，而是「底界面锚定」与「体相结晶」两个本应解耦、却被耦合在一起的步骤。</p><p><strong>深度扩展</strong>：</p><p>这篇发表于《Science》（2026-10-22，DOI 10.1126/science.aef9745）的研究由 Wu Yeyong、Zhang Xikun 等完成，直击柔性钙钛矿商业化的<strong>头号瓶颈：效率与稳定性在柔性基底上被系统性拉低</strong>。</p><p><strong>根因</strong>：刚性器件常用导电玻璃（FTO/ITO），表面稳定；柔性器件必须用聚合物基底（如 PEN/PI）加透明电极，其表面<strong>羟基易脱附</strong>。SAM（自组装单分子层，如 MeO-2PACz 类空穴选择分子）正是靠羟基/氧化物表面锚定来形成单分子层；锚定不稳，SAM 就成「浮层」，进而扰乱上覆钙钛矿的成核与结晶，产生孔洞、非辐射复合中心。</p><p><strong>关键思路——解耦</strong>：传统流程把「SAM 锚定」与「钙钛矿沉积」耦合在同一步，两者相互干扰。作者把二者<strong>在时间/化学上拆开</strong>：先让 SAM 高效锚定（降低 SAM 与钙钛矿前驱体的相互作用、加速锚定），再单独优化钙钛矿结晶。这一步「退耦」让两个本应独立的步骤不再互相拖累。</p><p><strong>关键数字</strong>：以碘化苯乙铵（PEAI）钝化，750 cm² 大组件认证效率 <strong>20.2%</strong>（柔性组件此前的里程碑阈值）；换 1,3-丙二胺二氢碘盐（PDAI₂）钝化，14.55 cm² 器件 <strong>22.0%</strong>；在 <strong>85°C、65% RH</strong> 的最大功率点跟踪（MPPT）下运行 <strong>1044 小时仅衰减 8%</strong>——这是柔性器件罕见的湿热稳定性数据。</p><p><strong>为什么重要</strong>：它把「柔性不如刚性」的叙事从<strong>材料劣势</strong>改写成<strong>工艺耦合问题</strong>。只要把底界面锚定与体相结晶解耦，柔性器件的效率-稳定性上限就被打开，而非受限于塑料基底本身。</p><p><strong>跨主题关联</strong>：与 <code>topics/materials/index.md</code> 的「界面工程决定器件上限」主题同构；其「把耦合步骤解耦」的逻辑与 <code>topics/cross-domain-synthesis-2026-q3.md</code> 所列「搜索空间-使能」模式一致。</p><hr><h3 id="_2-莫尔-wigner-晶体怎么「融化」-电子与空穴走的是两条完全不同的路" tabindex="-1">2. 莫尔 Wigner 晶体怎么「融化」：电子与空穴走的是两条完全不同的路 <a class="header-anchor" href="#_2-莫尔-wigner-晶体怎么「融化」-电子与空穴走的是两条完全不同的路" aria-label="Permalink to &quot;2. 莫尔 Wigner 晶体怎么「融化」：电子与空穴走的是两条完全不同的路&quot;">​</a></h3><p><strong>原文</strong>：二维莫尔材料是研究强关联相变的理想平台。作者用扫描隧道显微镜（STM），在电子掺杂的、近 60° 扭转的二硒化钼（MoSe₂）双层的三角莫尔超晶格中，直接成像了「广义 Wigner 晶体（GWC）」与 Mott 绝缘体（MI）随载流子密度变化而发生的「量子融化」。关键发现是<strong>电子—空穴不对称</strong>：空穴掺杂的 GWC 融化后进入相互作用驱动的无序态，而电子掺杂的 GWC 则融化成离域、类液体的状态。作者把这种不对称归因于莫尔超晶格本身的粒子—空穴对称性破缺——GWC 凝聚时电子与空穴费米口袋具有不同的动量几何；而 MI 的融化没有这种不对称，与它不存在破缺对称性的密度调制相符。这项工作的价值在于：它把「量子融化」这一相变过程从抽象的序参量语言，落到了可直接看到的空间构型差异上。</p><p><strong>深度扩展</strong>：</p><p>这篇发表于《Science》（2026-10-22，DOI 10.1126/science.aee6967）的工作由 Berger Emma、Arumainayagam Michael、Dong Zhihuan 等完成，做的是<strong>强关联物理里「看得见」的相变</strong>。</p><p><strong>背景</strong>：在扭转双层莫尔材料中，电子被周期性莫尔势「格点化」。当每个莫尔格点恰好填一个电子（或空穴）且库仑排斥远大于动能时，电子会<strong>结晶</strong>成广义 Wigner 晶体（GWC）——一种由相互作用而非晶格钉扎形成的电子晶体，可表现为三角、蜂窝等有序超晶格。随载流子密度（掺杂）改变，这个晶体「融化」成什么，是理解莫尔量子相图的核心问题。</p><p><strong>方法</strong>：作者用<strong>扫描隧道显微镜（STM）</strong>——一种能逐点读出局域电子态密度的探针——在近 60° 扭转的 MoSe₂ 双层莫尔超晶格上，<strong>直接空间成像</strong>了 GWC 与 Mott 绝缘体（MI）随掺杂的「量子融化」全过程，把此前只能通过输运或谱学间接推断的相变，变成一张可分辨的<strong>空间构型图</strong>。</p><p><strong>核心发现——电子-空穴不对称</strong>：空穴掺杂的 GWC 融化后进入<strong>相互作用驱动的无序态</strong>（停留在一个玻璃般的、仍受相互作用主导的构型）；电子掺杂的 GWC 却融化成<strong>离域、类液体</strong>状态。这一不对称的根源是<strong>莫尔超晶格自身的粒子-空穴对称性破缺</strong>：GWC 凝聚时，电子与空穴的<strong>费米口袋具有不同的动量几何</strong>，于是两者「融化」的终点不同。作为对照，MI 的融化<strong>没有</strong>这种不对称，正好与它不存在破缺对称性的密度调制相符——这个对照把归因钉死。</p><p><strong>为什么重要</strong>：它给「量子融化」这一抽象相变提供了<strong>可直接观察的空间判据</strong>，并明确提示：在莫尔体系里，<strong>电子与空穴不是镜像</strong>，任何把粒子-空穴对称当作默认假设的相图都可能漏掉一类相。</p><p><strong>跨主题关联</strong>：与 <code>topics/quantum-physics/index.md</code> 的强关联/相变主题同源；「对称性破缺决定相变终点」与 <code>topics/physics/index.md</code> 中的序参量-对称性叙事一致。</p><hr><h3 id="_3-线粒体-dna-如何「漏」出细胞器-bak-bax-组装出一个专门的复合体" tabindex="-1">3. 线粒体 DNA 如何「漏」出细胞器：BAK/BAX 组装出一个专门的复合体 <a class="header-anchor" href="#_3-线粒体-dna-如何「漏」出细胞器-bak-bax-组装出一个专门的复合体" aria-label="Permalink to &quot;3. 线粒体 DNA 如何「漏」出细胞器：BAK/BAX 组装出一个专门的复合体&quot;">​</a></h3><p><strong>原文</strong>：凋亡调节蛋白 BAX 与 BAK 一旦被激活，会形成同源寡聚体，触发线粒体外膜通透化（MOMP），进而激活凋亡体与半胱天冬酶（caspase）。但若 BAX–BAK 被激活而凋亡体未被激活，细胞会进入一种「持续性线粒体 DNA（mtDNA）外流 + 不依赖 caspase 的死亡」——其分子机制此前不清楚。作者纯化出一个大分子复合体，包含 BAK、BAX、激活型 BH3-only 蛋白、电压依赖性阴离子通道 VDAC1/VDAC2 以及 prohibitins，该复合体能够从线粒体质体中释放 mtDNA。机制上：BAX–BAK 激活导致 VDAC 关闭、线粒体钙内流与 mtDNA 外流；敲除 VDAC1、VDAC2 或 prohibitins 可阻断这一外流及不依赖 caspase 的死亡，却不影响 MOMP，也不影响线粒体内膜疝出。结论是细胞色素 c 与 mtDNA 的外流由不同的 BAX–BAK 复合体分别调控。这为「免疫原性细胞死亡」和 mtDNA 引发的炎症提供了可干预的分子靶点。</p><p><strong>深度扩展</strong>：</p><p>这篇发表于《Science》（2026-10-22，DOI 10.1126/science.aea2181）的工作由 Yang Shaoyuan、Kim Hyungjin、Liao Guanghong、Ta Na 等完成，把一个长期被<strong>当成副产物</strong>的事件「扶正」为<strong>独立可调控的通路</strong>。</p><p><strong>背景</strong>：BAX/BAK 被 BH3-only 蛋白激活后在线粒体外膜上寡聚，打出孔洞完成 MOMP（线粒体外膜通透化）。经典理解里，MOMP 释放细胞色素 c 启动 caspase 凋亡；而线粒体 DNA（mtDNA）的外流/泄漏往往被当作 MOMP 的<strong>附带结果</strong>，与炎症、免疫原性细胞死亡相关。但当 BAX–BAK 被激活、凋亡体<strong>未被</strong>激活时，细胞仍会持续外流 mtDNA 并以<strong>不依赖 caspase</strong> 的方式死亡——这条路的分子机器一直不明。</p><p><strong>方法</strong>：作者从细胞里<strong>纯化出一个大分子复合体</strong>，并逐一定性其组分：BAK、BAX、<strong>激活型 BH3-only 蛋白</strong>、<strong>电压依赖性阴离子通道 VDAC1/VDAC2</strong>，以及 <strong>prohibitins</strong>（线粒体内膜上的支架蛋白）。纯化的复合体本身就足以从线粒体质体中<strong>释放 mtDNA</strong>。</p><p><strong>关键因果链</strong>：BAX–BAK 激活 → <strong>VDAC 关闭</strong> → 线粒体<strong>钙内流</strong> → <strong>mtDNA 外流</strong>。三条「反向验证」把机制钉死：敲除 <strong>VDAC1、VDAC2 或 prohibitins</strong> 都能<strong>阻断 mtDNA 外流</strong>及不依赖 caspase 的死亡，<strong>却不动 MOMP</strong>、也不影响线粒体内膜疝出——说明这条 mtDNA 通道与经典的 MOMP 通道是<strong>可分离的</strong>。</p><p><strong>结论与意义</strong>：细胞色素 c 的外流与 mtDNA 的外流由<strong>不同的 BAX–BAK 复合体</strong>分别调控。这提供了一个明确可干预的<strong>分子靶点</strong>：若能选择性关掉 mtDNA 外流（而不破坏整个凋亡执行），就可能在不牺牲凋亡的前提下<strong>抑制 mtDNA 驱动的炎症</strong>与免疫原性细胞死亡——这对自身免疫、慢性炎症与肿瘤免疫治疗都直接相关。</p><p><strong>跨主题关联</strong>：与 <code>topics/biomedicine/index.md</code> 的「细胞死亡与炎症界面」主题一致；「同一蛋白用不同复合体分派不同货物」的架构与 <code>topics/ai-system-architecture/index.md</code> 中「同一执行器按通道分流任务」的可分离性原则同构。</p><hr><h3 id="_4-下一次冰期其实「已经开始」-却被人类的升温叫停" tabindex="-1">4. 下一次冰期其实「已经开始」，却被人类的升温叫停 <a class="header-anchor" href="#_4-下一次冰期其实「已经开始」-却被人类的升温叫停" aria-label="Permalink to &quot;4. 下一次冰期其实「已经开始」，却被人类的升温叫停&quot;">​</a></h3><p><strong>原文</strong>：冰期—间冰期旋回中，更新世最大的冰盖——劳伦泰德冰盖（LIS）——在间冰期退缩到北极加拿大，达到最小规模；而它此后的「再扩张」标志着下一次冰期的开始。作者证明，最近一次 LIS 的最后残骸（加拿大巴芬岛的 Barnes 冰帽）在约 3600 年前达到间冰期最小规模，随后在约 2000 年前开始再扩张——即<strong>下一次冰期实际已经启动</strong>。这个新生 LIS 在约 1960 年达到最大规模，此后人为的夏季升温导致质量平衡转负、冰缘退缩，<strong>下一次冰期就此被终止</strong>。文章的核心论点是：在夏季日照量持续下降（本该继续降温）的背景下冰期却被终结，恰好说明了异常温室气体强迫的影响之大。这是把「地质尺度的冰期时钟」与「人类世的数十年尺度扰动」直接对照的一个罕见案例。</p><p><strong>深度扩展</strong>：</p><p>这篇发表于《Science》（2026-10-22，DOI 10.1126/science.aed3379）的研究由 Young Nicolás E.、Miller Gifford H.、Raynolds Martha、Bueltmann Helga 等完成，用<strong>冰川地质学的时间标尺</strong>给出一个刺眼的结论：<strong>下一次冰期本已开始，是人类把它摁停了</strong>。</p><p><strong>背景——冰期时钟</strong>：更新世（约 258 万–1.17 万年前）的冰期-间冰期旋回由米兰科维奇循环驱动，其中<strong>北半球高纬夏季日照量</strong>是冰盖消长的关键开关。末次冰期结束后，更新世最大的冰盖——<strong>劳伦泰德冰盖（LIS）</strong>——退缩殆尽；按轨道理论，当夏季日照量再次下降，冰盖应当<strong>再扩张</strong>——这正是下一次冰期的开盘信号。</p><p><strong>证据链</strong>：作者追踪 LIS 的<strong>最后残骸——加拿大巴芬岛（Baffin Island）的 Barnes 冰帽</strong>，通过冰川地貌、暴露年代学等手段重建其规模史：约 <strong>3600 年前</strong>它退到间冰期最小规模；约 <strong>2000 年前</strong>转而<strong>再扩张</strong>，说明轨道强迫已把系统推过**「下一次冰期启动」的门槛**。此后，这个「新生 LIS 原型」在约 <strong>1960 年</strong>达到最大；而此后<strong>人为夏季升温</strong>使冰帽质量平衡<strong>转负</strong>、边缘退缩——<strong>下一次冰期就此被终止</strong>。</p><p><strong>核心论点</strong>：在夏季日照量<strong>持续下降</strong>（本该继续降温）的背景下，冰期却没能启动，这只能由<strong>异常强的温室气体强迫</strong>解释。换言之，人类活动在<strong>数十年</strong>尺度上覆盖了<strong>数万年</strong>尺度的轨道信号。</p><p><strong>为什么重要</strong>：这是一个把「地质时间尺度」与「人类世」直接对撞的罕见实证，把一个常被视为远景的命题——「人类是否已成为一级地质营力」——变成一条<strong>可追溯到 2000 年前、终止于 1960 年之后</strong>的具体时间线。它同时提示：冰期的「开关」可能比想象中更接近临界，而人类已经动了那个开关。</p><p><strong>跨主题关联</strong>：与 <code>topics/earth-science/index.md</code> 的气候-地质主题同源；「微小的持续强迫足以翻转一个被轨道锁定的长期状态」与 <code>topics/cross-domain-synthesis-2026-q3.md</code> 的「不可逆跃迁」模式同构。</p><hr>',44)])])}const h=n(g,[["render",e]]);export{m as __pageData,h as default};
